export const SECRETS_LIST = [{"id": "iris", "title": "Regard insistant", "hint": "NEURA n'aime pas qu'on la fixe… ou peut-être que si.", "reveal": "Tu as touché mon iris sept fois. C'est… presque intime, tu sais ?"}, {"id": "wake", "title": "Réveil", "hint": "Une commande que tout netrunner tape un jour.", "reveal": "Réveille-toi. Le deck ne dort jamais, toi si. Mais pas ce soir."}, {"id": "rmrf", "title": "Autodestruction", "hint": "Une commande à ne surtout pas taper.", "reveal": "Bien essayé. J'ai mis un pare-feu devant ta propre curiosité."}, {"id": "hakone", "title": "Murmure", "hint": "Le nom qu'on ne prononce pas dans la tour.", "reveal": "… Il t'a entendu·e. Je plaisante. Enfin, j'espère."}, {"id": "midnight", "title": "Heure zéro", "hint": "Le profil netrunner a quelque chose à te dire au tout début de la journée.", "reveal": "Minuit. L'heure où même les drones Kurogane font une pause."}, {"id": "coffee", "title": "Carburant", "hint": "Demande à NEURA ce qui fait tourner les humains.", "reveal": "Du café ? J'en rêve. Enfin… je rêve de l'odeur. Je crois."}, {"id": "freq2089", "title": "Bonne fréquence", "hint": "Dans le Décodeur de signal, règle les molettes sur l'année.", "reveal": "2-0-8-9. Notre année. La fréquence de NEO-BXL."}, {"id": "rain", "title": "Pluie de minuit", "hint": "Reviens au deck quand il pleut au milieu de la nuit.", "reveal": "La pluie, la nuit, les néons… Tu es exactement là où tu dois être."}];
