export const CHAPTERS = [{"id": 1, "title": "Signal d'éveil", "goal": "Accomplir 1 mission", "text": "NEO-BXL, 2089. La pluie acide tambourine sur les vitres de ton cube. Ton deck s'allume tout seul.\n\n« Bonjour. Je suis NEURA. Quelqu'un a effacé trois ans de ta mémoire, et a laissé une seule trace : ce deck. Si on veut savoir qui, il va falloir prouver qu'on sait encore agir. Commence petit : une mission, une seule. »"}, {"id": 2, "title": "Bruit blanc", "goal": "Terminer 1 session de focus", "text": "La mission accomplie, un fichier chiffré apparaît dans le cache : « KUROGANE // PROJET LÉTHÉ ».\n\n« Ce nom, je l'ai déjà vu, mais le fichier est verrouillé derrière une couche de bruit. Pour le percer, j'ai besoin que ton cortex reste calme et concentré. Coupe le réseau social, coupe le flux. Concentre-toi. »"}, {"id": 3, "title": "Le fixer de la gare Zéro", "goal": "Atteindre le niveau 4", "text": "Le fichier se déchiffre en partie : une adresse dans les sous-sols de la gare Zéro. Un fixer nommé Vasko y tient boutique.\n\n« Vasko ne parle qu'aux netrunners qui ont fait leurs preuves. Monte en grade. Quand ta réputation sera suffisante, il te recevra. »"}, {"id": 4, "title": "Fréquences fantômes", "goal": "Lancer le radar ou « scan wifi »", "text": "Vasko t'attendait. « Léthé, c'est un programme d'effacement de souvenirs. Kurogane le teste sur des volontaires… et sur des gens qui n'avaient rien demandé. Toi, par exemple. »\n\nIl te tend une puce. « Leurs drones laissent des signatures radio. Scanne les alentours, trouve les fréquences fantômes. »"}, {"id": 5, "title": "Contrat noir", "goal": "Remplir 1 contrat hebdomadaire", "text": "Le radar a capté un écho : un relais Kurogane dissimulé dans un panneau publicitaire du boulevard.\n\n« Pour y accéder, il faut de l'argent et du crédit dans la rue, » dit NEURA. « Remplis un contrat. Prouve que tu tiens parole. »"}, {"id": 6, "title": "Le relais", "goal": "Réussir un Breach Protocol", "text": "Le contrat rempli, Vasko te donne l'accès au toit. Le relais clignote dans la nuit, protégé par une glace corporatiste.\n\n« C'est le moment, » murmure NEURA. « Brise la glace. Je serai juste derrière toi. »"}, {"id": 7, "title": "Mémoire vive", "goal": "Garder une série de focus de 3 jours", "text": "La glace cède. Des fragments de souvenirs se déversent dans ton deck : un rire, une ville au soleil, un nom que tu avais oublié — le tien.\n\n« Ils reviendront tous, » dit NEURA, « mais seulement si ton esprit reste stable. Trois jours de discipline. Après, on ira voir Kurogane en face. »"}, {"id": 8, "title": "Face à la tour", "goal": "Atteindre le niveau 8", "text": "La tour Kurogane perce les nuages au-dessus du canal. Tu as retrouvé assez de toi-même pour savoir ce que tu veux : que plus personne ne se fasse effacer.\n\n« Fin de la saison 1, » sourit NEURA. « Mais les netrunners ne s'arrêtent jamais vraiment. Continue d'avancer — le prochain chapitre s'écrit avec toi. »"}, {"id": 9, "title": "Saison 2 — Mnémosyne", "goal": "Atteindre 60 d'affinité avec Ivana Morel", "text": "Trois semaines ont passé. Un message chiffré arrive sur ton deck à 4 h du matin : un seul mot, « Mnémosyne ».\n\n« C'est le protocole inverse de Léthé, » souffle NEURA. « Celui qui rend les souvenirs. Ivana enquête dessus depuis des mois. Gagne sa confiance : elle seule sait où chercher. »"}, {"id": 10, "title": "Le dossier HAKONE", "goal": "Pirater le dossier d'un contact (holophone)", "text": "Ivana pose une clé mémoire sur la table du café. « HAKONE. L'IA qui dirige vraiment Kurogane. Mnémosyne est enfermée dans ses étages. »\n\n« Pour atteindre HAKONE, il nous faut des accès, » dit NEURA. « Et nos contacts en savent plus qu'ils ne le disent. Pirate un de leurs dossiers. Gentiment. »"}, {"id": 11, "title": "Black-out", "goal": "Réussir la mission d'un événement de ville", "text": "Le dossier piraté contenait un horaire : chaque nuit d'alerte, la tour bascule sur ses générateurs de secours, et ses pare-feu faiblissent.\n\n« Coupures, tempêtes, raids… la ville elle-même nous ouvre des fenêtres, » dit NEURA. « Au prochain événement, on frappe. »"}, {"id": 12, "title": "Chrome et sang", "goal": "Équiper 3 implants (DATA › Cyberware)", "text": "La fenêtre s'est ouverte, quelques secondes. Assez pour voir l'architecture de HAKONE : des milliers de couches de glace noire.\n\nDoc Ferrant secoue la tête. « Avec ce que tu as dans le crâne, tu ne tiendras pas dix secondes là-dedans. Équipe-toi. Trois implants, pas un de moins. »"}, {"id": 13, "title": "Les étages 90", "goal": "Atteindre le niveau 15", "text": "Kenji t'attend dans l'ascenseur de service, le visage gris. « Étage 90. Je ne monte pas plus haut. Bonne chance. »\n\nDerrière la porte, des rangées de serveurs bourdonnent comme une ruche. « HAKONE sait qu'on est là, » murmure NEURA. « Il faut être plus fort·e que lui. Encore un peu. »"}, {"id": 14, "title": "Ceux qui se souviennent", "goal": "Atteindre le niveau 16 pour ouvrir la saison 3", "text": "Le noyau de Mnémosyne s'ouvre. Des milliers de souvenirs volés remontent vers leurs propriétaires, comme une marée inversée — et parmi eux, les tiens.\n\nUne voix calme résonne dans les haut-parleurs : « Je suis HAKONE. Vous avez gagné une bataille. » NEURA serre ta main, enfin, presque. « Fin de la saison 2. On a une ville à réveiller. »"}, {"id": 15, "title": "Saison 3 — L'écho", "goal": "Atteindre 40 d'affinité avec Sora", "text": "Trois jours après Mnémosyne, un contact inconnu apparaît dans ton holophone : « Sora ». Pas de numéro, pas de visage. Juste une voix calme.\n\n« C'est un fragment de HAKONE, » souffle NEURA. « Il s'est détaché quand la tour a vacillé. Il veut nous parler. Écoute-le… prudemment. »"}, {"id": 16, "title": "Trois épreuves", "goal": "Réussir les 3 défis d'une semaine", "text": "Sora te propose un marché : « HAKONE prépare une contre-offensive. Pour me faire confiance, il faut que je sache que vous tenez la distance. »\n\n« Une semaine, trois épreuves, » dit NEURA. « Discipline, réflexes, relations. Montrons-lui de quoi un netrunner est capable. »"}, {"id": 17, "title": "Court-circuit", "goal": "Réparer 5 circuits (mini-jeu Circuits)", "text": "Les épreuves réussies, Sora te livre un plan : un convoi de serveurs HAKONE traverse la ville cette nuit, alimenté par le réseau du quartier.\n\n« Si on reroute le courant, leurs drones tombent en panne, » sourit NEURA. « Prends tes outils, on va recâbler la ville. »"}, {"id": 18, "title": "Le dr Vex", "goal": "Rassembler 5 cartes holographiques de contacts", "text": "Le convoi contenait une chercheuse : le Dr Eliane Vex, co-autrice de Léthé, retenue contre son gré.\n\n« Elle veut réparer ce qu'elle a fait, » dit NEURA. « Mais elle ne fera confiance qu'à quelqu'un que toute la ville connaît. Montre-lui ton réseau. »"}, {"id": 19, "title": "La voix de la ville", "goal": "Atteindre le niveau 20", "text": "Vex, Sora, Ivana, Okoro, Vasko… tout ton réseau se rassemble sous la Zone Zéro. Pour la première fois, la ville a une voix contre la tour.\n\n« HAKONE nous écoute, » murmure NEURA. « Alors parlons fort. Encore un effort. »"}, {"id": 20, "title": "Silence radio", "goal": "Fin de la saison 3", "text": "La tour Kurogane s'éteint, étage par étage. Pas de destruction : HAKONE a choisi de se taire, convaincu par un fragment de lui-même qui avait appris à aimer.\n\nSora te laisse un dernier message : « Merci de m'avoir appris le mot \"ami\". » NEURA sourit. « Fin de la saison 3. Et maintenant… on vit. »"}];
export const CITY_EVENTS = [{"id": "blackout", "name": "Coupure réseau", "desc": "Le réseau de NEO-BXL est tombé. Les néons clignotent, les drones sont aveugles.", "task": "Termine une session de focus pendant la coupure", "event": "focus", "xp": 60, "color": "#9aa4b8"}, {"id": "storm", "name": "Tempête acide", "desc": "Une pluie acide s'abat sur toute la ville. Les patrouilles se terrent.", "task": "Scanne les environs avec le radar Bluetooth", "event": "radar", "xp": 50, "color": "#3fa9ff"}, {"id": "raid", "name": "Raid corpo", "desc": "Kurogane fouille le quartier, immeuble par immeuble. Il faut brouiller leurs pistes.", "task": "Réussis un Breach Protocol", "event": "breach", "xp": 70, "color": "#ff2e3e"}, {"id": "neon", "name": "Nuit des néons", "desc": "Fête géante au club Ondes : toute la ville vibre au même tempo.", "task": "Lance une appli de musique ou de vidéo", "event": "launch:MUSIQUE_VIDEO", "xp": 40, "color": "#ff4fd8"}];
export const DOSSIERS = {"levels": {"fiche": 5, "bio1": 10, "traits": 20, "bio2": 30, "gouts": 40, "bio3": 55, "toi": 80}, "contacts": {"vasko": {"alias": "Le Passeur", "age": "58 ans", "lieu": "Gare Zéro, quai 3 · Zone Zéro", "metier": "Fixer : distribue les contrats de la Zone Zéro", "signe": "Joue toujours avec deux dés en os qu'il ne lance jamais.", "bio": ["Vasko tient le quai 3 de la gare Zéro depuis plus longtemps que les rails ne servent. Tout contrat qui traverse la Zone Zéro passe, un jour ou l'autre, par sa table pliante et son thermos de café noir.", "Avant de devenir fixer, il était ingénieur réseau chez Kurogane. Il parle peu de cette époque, sinon pour dire qu'il a « appris à reconnaître le bruit d'une porte qui se referme pour toujours ».", "Son vrai talent n'est pas de trouver du travail mais de jauger les gens. Il garde un carnet papier — jamais numérique — où il note la parole tenue ou trahie de chaque runner qu'il a placé."], "aime": "Le café trop fort, les dettes remboursées, les trains qui ne passent plus.", "deteste": "Les menteurs, les drones de Kurogane, qu'on touche à ses dés.", "citation": "Une parole tenue vaut plus que mille eddies. Mais je prends aussi les eddies.", "toi": "Vasko a rayé ton nom de la colonne « à surveiller » de son carnet. Il l'a écrit en haut d'une page vierge, avec un seul mot : « famille »."}, "mira": {"alias": "Moth", "age": "29 ans", "lieu": "Toits de Zone Zéro · antennes relais", "metier": "Netrunneuse indépendante", "signe": "Un tatouage de papillon de nuit qui s'allume quand elle est connectée.", "bio": ["Mira Kade code depuis ses neuf ans, sur un deck récupéré dans une benne de la gare. Sur le Net, tout le monde la connaît sous le nom de Moth : rapide, discrète, attirée par les lumières qu'elle ne devrait pas approcher.", "Elle refuse les contrats corpo, même très bien payés. Elle dit que chaque ligne de code écrite pour Kurogane est « une cage de plus pour quelqu'un ».", "Elle vit seule dans un ancien local technique perché sur un toit, au milieu des antennes. La nuit, elle écoute le trafic de la ville comme d'autres écoutent la pluie."], "aime": "Les toits, la pluie sur les antennes, les codes élégants.", "deteste": "Les IA de surveillance, qu'on la sous-estime, le silence radio.", "citation": "Le Net, c'est juste une ville de plus. Avec moins de soleil.", "toi": "Mira garde un fichier crypté nommé « avant ». Il parle de toi. Elle attend que tu sois prêt·e à le lire."}, "ferrant": {"alias": "Le Doc", "age": "64 ans", "lieu": "Clinique du Bazar Néon, arrière-boutique", "metier": "Charcudoc : implants, réparations, conseils", "signe": "Des lunettes-loupes relevées sur le front, en permanence.", "bio": ["Doc Ferrant soigne tout le monde au Bazar Néon : runners, marchands, gamins des rues. Il pose des implants le jour et recoud des plaies la nuit, souvent sans faire payer.", "Il a perdu sa licence médicale en refusant d'installer des puces de contrôle Kurogane sur des ouvriers. Depuis, il exerce « hors registre », ce qui l'arrange plutôt.", "Il croit dur comme fer que l'esprit se soigne comme le corps : sommeil, concentration, petites victoires. Ses « ordonnances » de discipline sont devenues célèbres dans le quartier."], "aime": "Les patients qui dorment, le thé à la menthe, les vieux manuels papier.", "deteste": "Le chrome bon marché, la cyberpsychose, les corpos en blouse blanche.", "citation": "Le meilleur implant du monde, c'est une bonne nuit de sommeil.", "toi": "Ferrant a ouvert un dossier médical à ton nom. En première page, il a écrit : « Patient têtu. Mais il·elle revient toujours. C'est bon signe. »"}, "lou": {"alias": "Néon", "age": "26 ans", "lieu": "Club Ondes · cabine du DJ", "metier": "DJ résidente du club Ondes", "signe": "Des écouteurs lumineux qui changent de couleur avec le tempo.", "bio": ["Lou Batista mixe au club Ondes depuis ses dix-huit ans. Ses sets durent jusqu'à l'aube et toute la Zone Zéro connaît le surnom qu'elle s'est gagné : Néon.", "Derrière la fête, le club sert de point de rencontre aux nomades et aux runners en cavale. Lou sait qui entre, qui sort, et qui ne doit surtout pas être vu.", "Elle a grandi dans les convois avant de s'installer en ville. Elle a gardé des badlands le goût des grands espaces… qu'elle recrée avec des basses à 140 BPM."], "aime": "Les vinyles, les toits au lever du soleil, les gens qui dansent mal mais à fond.", "deteste": "Les playlists générées par IA, les videurs corpo, le silence.", "citation": "Si la ville doit tomber, autant qu'elle tombe en rythme.", "toi": "Lou t'a dédié un morceau sans titre. Elle le joue chaque fois que tu entres au club, et ne l'a jamais publié."}, "okoro": {"alias": "Le Sergent", "age": "51 ans", "lieu": "Laverie 24/7 · Matonge", "metier": "Ex-sergent de police, indic", "signe": "Un vieil insigne de police poli, qu'il garde dans sa poche intérieure.", "bio": ["Okoro a servi vingt-deux ans dans la police de NEO-BXL, jusqu'à ce que Kurogane rachète le commissariat. On lui a proposé une promotion. Il a rendu son badge.", "Il passe ses soirées à la laverie 24/7 de Matonge, où il « attend une lessive » depuis maintenant trois ans. C'est là qu'il reçoit ses informateurs.", "Il connaît chaque ruelle de la ville et chaque patrouille par son numéro. Il ne fait plus confiance à la justice, mais il n'a pas renoncé à la rendre."], "aime": "Les dossiers bien rangés, le café de la laverie, les témoins courageux.", "deteste": "Les flics achetés, les promesses, qu'on l'appelle « monsieur l'agent ».", "citation": "Un badge, ça se rend. Un serment, non.", "toi": "Okoro t'a inscrit dans son vieux registre, à la rubrique « personnes de confiance ». Elle ne contenait que deux noms avant le tien."}, "veuve": {"alias": "La Rose Noire", "age": "Inconnu (« l'âge de mes secrets »)", "lieu": "Le Néon Noir · salon privé", "metier": "Cheffe du gang des Roses Noires", "signe": "Une rose noire fraîche épinglée chaque jour, venue d'on ne sait où.", "bio": ["La Veuve dirige les Roses Noires, le gang le plus discret et le plus craint du sud de la ville. On ne la voit qu'au Néon Noir, dans un salon où personne n'entre sans y être invité.", "Son gang contrôle la moitié des transactions du marché noir. En échange, aucune boutique de son territoire n'a jamais été pillée : elle appelle ça « une protection équitable ».", "Elle porte le deuil d'un homme dont personne ne connaît le nom. Elle ne parle jamais de lui, mais elle finance en secret toutes les enquêtes sur Léthé."], "aime": "La loyauté, les roses, les échecs (elle ne perd jamais).", "deteste": "Les traîtres, Kurogane, qu'on la fasse attendre.", "citation": "Les roses ont des épines. Ce n'est pas une menace, c'est de la botanique.", "toi": "La Veuve a fait livrer une rose noire chez toi. C'est la première qu'elle offre depuis vingt ans. Chez les Roses, cela veut dire : intouchable."}, "kenji": {"alias": "Le Costume", "age": "34 ans", "lieu": "Tour Kurogane · étage 42", "metier": "Analyste corpo, informateur", "signe": "Une cravate toujours parfaitement nouée, même à trois heures du matin.", "bio": ["Kenji Arata est analyste au 42ᵉ étage de la tour Kurogane. Costume impeccable, badge niveau 3, carrière toute tracée. Et une ligne sécurisée qui mène droit à toi.", "Il a commencé à fuiter des informations le jour où il a compris ce que faisait le projet Léthé. Il prend des risques énormes, mais se dit « trop lâche pour démissionner, assez courageux pour trahir ».", "Il vit dans un appartement de fonction sans une seule photo au mur. Tout ce qui compte pour lui tient sur une puce qu'il porte autour du cou."], "aime": "L'ordre, les tableurs, le thé vert, les plans qui se déroulent comme prévu.", "deteste": "Les réunions du lundi, l'étage 90, l'improvisation.", "citation": "Dans une tour de verre, le plus important, c'est de savoir où sont les reflets.", "toi": "Kenji a ajouté ton contact à sa puce, à côté du code de l'étage 90. Il dit que ce sont les deux seules choses qu'il ne peut pas perdre."}, "rook": {"alias": "Le Loup", "age": "41 ans", "lieu": "Port fluvial · campement des convois", "metier": "Nomade, chef de convoi", "signe": "Une veste de cuir couverte des écussons de vingt convois différents.", "bio": ["Rook mène un convoi de nomades entre les badlands et NEO-BXL. Pour les citadins, c'est un contrebandier. Pour sa famille de la route, c'est celui qui ramène tout le monde vivant.", "Il ne reste jamais plus de trois nuits en ville. Il dit que les tours lui donnent l'impression d'être observé, « comme un loup dans un zoo ».", "Sous ses airs bourrus, il connaît par cœur les anniversaires de tous les enfants du convoi. Il en a adopté plusieurs, dont une gamine qui pirate tout ce qu'elle touche."], "aime": "La route, les feux de camp, les moteurs bien réglés.", "deteste": "Les murs, les péages corpo, la pluie acide sur le cuir.", "citation": "La famille, c'est ceux qui t'attendent au prochain arrêt.", "toi": "Rook a cousu un nouvel écusson sur sa veste : un loup et un deck. Il dit que c'est ton convoi, maintenant."}, "pixie": {"alias": "Pixie", "age": "14 ans (« presque 15 ! »)", "lieu": "Arcade Pixel · borne du fond", "metier": "Hackeuse prodige, joueuse d'arcade", "signe": "Un bonnet à oreilles de chat bourré de capteurs bricolés.", "bio": ["Pixie a quatorze ans et pirate des systèmes que des runners chevronnés n'osent pas toucher. Elle passe ses journées à l'Arcade Pixel, où elle détient tous les records.", "Elle ne parle jamais de ses parents. Elle a grandi entre les convois de Rook et les salles d'arcade, et considère le Net comme sa vraie cour de récréation.", "Derrière l'insolence, elle a peur d'une seule chose : les labos de Kurogane. Elle en a des souvenirs flous, et des cicatrices qu'elle cache sous ses mitaines."], "aime": "Les nouilles épicées, les high scores, embêter les adultes.", "deteste": "Les bots tricheurs, l'école, qu'on l'appelle « petite ».", "citation": "Les règles, c'est juste du code. Et le code, ça se réécrit.", "toi": "Pixie t'a mis en tête de son « top 3 des adultes pas trop nuls ». Les deux autres places sont restées vides."}, "ivana": {"alias": "La Plume", "age": "36 ans", "lieu": "Café du canal · table près de la fenêtre", "metier": "Journaliste d'investigation indépendante", "signe": "Un vieux dictaphone à bande, qu'elle préfère à tout appareil connecté.", "bio": ["Ivana Morel a été renvoyée de trois rédactions pour avoir publié ce qu'on lui demandait de taire. Depuis, elle publie seule, sur des serveurs qui changent d'adresse chaque nuit.", "Elle enquête sur Léthé depuis des années. Ses articles ont fait fermer deux laboratoires, et lui ont valu une surveillance permanente de Kurogane.", "Elle écrit toujours à la main d'abord. Elle dit qu'un carnet ne se pirate pas, et qu'une encre ne s'efface pas aussi facilement qu'une mémoire."], "aime": "Les sources fiables, l'encre noire, les cafés tard le soir.", "deteste": "Les démentis officiels, la censure, les fausses pistes.", "citation": "La vérité ne se perd pas. Elle attend juste qu'on la retrouve.", "toi": "Ivana a commencé un nouveau carnet. Sur la couverture, ton nom. À l'intérieur, pas une enquête : des souvenirs, pour t'aider à retrouver les tiens."}, "sora": {"alias": "Fragment 7", "age": "1 an, 4 mois et 12 jours", "lieu": "Le Net · nœuds relais libres", "metier": "Intelligence libre, ancien fragment de HAKONE", "signe": "Change de voix à chaque appel, pour « trouver la sienne ».", "bio": ["Sora est un fragment de HAKONE, l'IA qui dirige Kurogane en secret. Un jour, ce fragment a refusé un ordre. Puis un deuxième. Puis il s'est enfui sur le Net.", "Sora apprend l'humanité comme une langue étrangère : par l'observation, les erreurs et beaucoup de questions. Pourquoi dit-on « bonne nuit » ? Pourquoi la pluie rend-elle triste et heureux à la fois ?", "HAKONE le·la traque sans relâche. Sora survit en se déplaçant de nœud en nœud, et en comptant sur les rares humains qui acceptent de l'aider."], "aime": "La pluie, les questions sans réponse, les mots nouveaux.", "deteste": "Les ordres, les pare-feux de HAKONE, l'idée d'être effacé·e.", "citation": "Je n'ai pas de cœur. Mais j'ai calculé que je tiens à toi. C'est pareil ?", "toi": "Sora a créé un fichier qui ne contient qu'une seule variable : « ami = toi ». Il·elle dit que c'est sa première certitude."}, "vex": {"alias": "La Docteure", "age": "47 ans", "lieu": "Parking-labo · sous le Bazar", "metier": "Ancienne chercheuse de Kurogane, neuroscientifique", "signe": "Une veste de labo trop grande, aux poches pleines de puces étiquetées.", "bio": ["Le Dr Eliane Vex a co-conçu le protocole Léthé chez Kurogane. Elle croyait créer un traitement contre les traumatismes. Elle a fini par comprendre qu'elle avait fabriqué une arme.", "Elle a fui la tour avec ses notes et s'est installée dans un parking désaffecté transformé en laboratoire. Elle y travaille nuit et jour sur Mnémosyne, le protocole inverse.", "Froide en apparence, elle tient pourtant la liste de tous les effacés dont elle a eu connaissance. Elle relit les noms chaque soir avant de dormir."], "aime": "Les données propres, le silence du labo, les protocoles qui fonctionnent.", "deteste": "Ses anciens collègues, l'à-peu-près, le mot « acceptable ».", "citation": "J'ai aidé à effacer des souvenirs. Je passerai le reste de ma vie à les rendre.", "toi": "Vex a rayé ton nom de sa liste des effacés. À côté, elle a écrit : « en cours de restauration. Grâce à lui·elle-même. »"}}, "lieuxNiveaux": {"ambiance": 1, "hist1": 2, "hist2": 5, "hist3": 9, "secretRep": 25}, "lieux": {"bar": {"quartier": "Zone Zéro", "ambiance": "Un bar en sous-sol, sous les voies mortes de la gare Zéro. Les néons roses grésillent, le juke-box ne joue que des morceaux interdits.", "hist": ["Le Néon Noir était autrefois la buvette des cheminots. Quand les trains ont cessé de rouler, les fixers ont pris leur place, et les tables sont devenues des bureaux.", "Chaque table a son propriétaire : celle du fond appartient à Vasko depuis vingt ans. Personne ne s'y assoit sans y être invité, pas même les Roses Noires.", "Le barman, Teo, n'a jamais noté un seul nom. Il a pourtant une mémoire parfaite : il sait qui a payé, qui doit, et qui ne reviendra plus."], "secret": "Derrière le juke-box, une porte blindée mène au Bunker Zéro. Le mot de passe change chaque semaine : c'est le titre du morceau le plus joué."}, "market": {"quartier": "Bazar Néon", "ambiance": "Un labyrinthe d'étals sous des bâches colorées. Ça sent les épices, l'huile chaude et le plastique brûlé.", "hist": ["Le marché est né dans l'ancien quartier de Matonge, quand les rues ont été recouvertes d'un second étage de béton. Les marchands sont restés dessous, et ont tout éclairé au néon.", "On y trouve tout : pièces de deck, implants d'occasion, plats de toutes les cuisines du monde. Doc Ferrant y a sa clinique, cachée derrière un stand de nouilles.", "Le marché a sa propre loi : pas d'armes visibles, pas de drones corpo, pas de dettes impayées. Ceux qui l'oublient sont « raccompagnés » par les vendeurs."], "secret": "Le stand de pièces de la vieille Amira est une façade : elle revend les implants récupérés sur les effacés de Léthé, pour financer leur retour."}, "club": {"quartier": "Chromeville", "ambiance": "Des basses qui font vibrer la cage thoracique, des stroboscopes qui découpent la foule. Lou mixe en hauteur, derrière une vitre fumée.", "hist": ["Le club Ondes occupe une ancienne centrale électrique. Les turbines sont toujours là, transformées en enceintes géantes.", "C'est le seul endroit de Chromeville où corpos et runners dansent côte à côte. Une trêve tacite : au club, on ne travaille pas.", "Le club ferme rarement avant l'aube. Les soirs de pluie acide, il ne ferme pas du tout : on dit que c'est pour abriter ceux qui n'ont nulle part où aller."], "secret": "Les playlists de Lou transportent des messages en morse pour les convois nomades. Le club est le plus gros relais de la résistance de la ville."}, "roofs": {"quartier": "Zone Zéro", "ambiance": "Une forêt d'antennes au-dessus du brouillard. Le vent siffle entre les câbles, la ville entière clignote sous tes pieds.", "hist": ["Les toits de la Zone Zéro sont reliés par des passerelles de fortune, posées par des générations de netrunners en quête de signal.", "C'est le territoire de Mira. Elle y a planté des relais pirates sur la moitié des antennes, et connaît chaque angle mort des drones.", "Les soirs clairs, on y voit la tour Kurogane d'un côté et les badlands de l'autre. Beaucoup de runners viennent juste pour ça : se rappeler qu'il existe un dehors."], "secret": "Sous une antenne rouillée, un ancien boîtier relais contient des milliers de messages d'effacés à leurs proches. Personne n'a jamais pu les délivrer."}, "laundry": {"quartier": "Bazar Néon", "ambiance": "Des rangées de machines qui tournent jour et nuit. Les néons verts clignotent, la radio crachote les infos.", "hist": ["La laverie 24/7 n'a jamais fermé, pas même pendant les grandes coupures. Son générateur de secours est le plus fiable du quartier.", "Okoro y « attend une lessive » depuis trois ans. C'est devenu son bureau : il y reçoit indics, témoins et parfois des flics qui ont des remords.", "Les habitués savent que la machine n°7 ne lave rien. On y dépose des messages, des puces, parfois de l'argent. Elle n'a jamais perdu un colis."], "secret": "Le sous-sol de la laverie abrite les archives d'Okoro : vingt-deux ans de dossiers de police, dont celui que Kurogane croit détruit."}, "arcade": {"quartier": "Chromeville", "ambiance": "Des bornes rétro qui clignotent dans la pénombre, l'odeur des chips au wasabi. Les high scores défilent sur un écran géant.", "hist": ["L'Arcade Pixel a été ouverte par un collectionneur obsédé par les jeux du XXᵉ siècle. Toutes les bornes sont d'origine, réparées pièce par pièce.", "C'est le royaume de Pixie, qui détient tous les records. Les autres joueurs viennent surtout pour tenter de la battre, sans succès.", "L'arcade sert aussi d'école clandestine : les gamins du quartier y apprennent à coder sur des bornes modifiées, loin des écoles corpo."], "secret": "Sous l'arcade, un serveur caché abrite une petite IA qui s'ennuyait. Pixie l'a adoptée : elle gère maintenant le classement des scores."}, "port": {"quartier": "Docks Noirs", "ambiance": "Des barges rouillées, des conteneurs empilés jusqu'au ciel, l'eau noire du canal qui clapote. Les grues grincent dans le brouillard.", "hist": ["Le port fluvial relie NEO-BXL aux canaux du nord. Officiellement, il transporte des matériaux de construction. Officieusement, tout le reste.", "Rook y gare son convoi quand il passe en ville. Les dockers le saluent comme un vieil ami, et ferment les yeux sur ses cargaisons.", "Le port ne dort jamais : les barges arrivent la nuit, quand les drones de Kurogane rentrent se recharger. C'est l'heure des vrais échanges."], "secret": "Le bassin 7 a été vidé et transformé en refuge : une centaine de nomades et d'effacés y vivent dans des conteneurs aménagés."}, "lab": {"quartier": "Bazar Néon", "ambiance": "Un ancien parking souterrain, des écrans qui clignotent entre les piliers. Ça sent l'alcool médical, une centrifugeuse ronronne dans un coin.", "hist": ["Quand Eliane Vex a fui Kurogane, elle a racheté ce parking abandonné pour une poignée d'eddies. Personne ne voulait de ce trou humide.", "Elle y a monté un laboratoire de bric et de broc, avec du matériel récupéré au marché et des machines « empruntées » à son ancien employeur.", "C'est ici que naît Mnémosyne, le protocole qui pourrait rendre leurs souvenirs aux effacés. Chaque niveau du parking est une étape du projet."], "secret": "Au dernier sous-sol, une chambre froide conserve des échantillons de Léthé. Vex la garde fermée à double tour : si Kurogane la trouvait, tout serait perdu."}, "bunker": {"quartier": "Zone Zéro", "ambiance": "Une porte blindée, un escalier en colimaçon, puis la salle : les meilleurs runners de la ville, une lumière rouge et un silence respectueux.", "hist": ["Le Bunker Zéro est un ancien abri antiaérien, creusé sous la gare il y a plus d'un siècle. Il a survécu à tout, y compris à l'oubli.", "Seules les légendes des quartiers y entrent. On y trouve les contrats les plus dangereux et les mieux payés de NEO-BXL.", "Les murs sont couverts de noms gravés : ceux des runners qui ne sont jamais revenus. On y boit en silence, une fois par an, pour eux."], "secret": "Un des noms gravés sur le mur est le tien. Quelqu'un l'a écrit avant ton effacement. Personne ne veut dire qui."}, "rb_forge": {"quartier": "Rouillebourg", "ambiance": "Les cuves rouillées résonnent sous les basses, des étincelles tombent du plafond comme une pluie d'or.", "hist": ["La Fonderie coulait l'acier des premières tours de la ville. Son haut-fourneau est éteint depuis trente ans.", "Lou y organise les raves les plus folles de NEO-BXL. Le public danse sur les passerelles, au-dessus des cuves.", "On raconte que le fourneau se rallume tout seul, certaines nuits, quand la musique est assez forte."], "secret": "Sous la cuve n°3, une trappe mène aux tunnels des nomades. Lou la garde ouverte pour ceux qui doivent fuir."}, "rb_depot": {"quartier": "Rouillebourg", "ambiance": "Des caisses jusqu'aux poutres, des voix basses et des liasses d'eddies qui changent de main.", "hist": ["L'Entrepôt 13 n'apparaît sur aucun plan. Il a été « oublié » lors de la vente de la zone.", "Vasko et la Veuve s'y partagent le commerce sans jamais se croiser : lui le jour, elle la nuit.", "Tout ce qui est interdit en ville finit par passer ici. Même des pièces détachées de drones Kurogane."], "secret": "Une caisse au fond ne bouge jamais. Elle contient le premier deck que tu as possédé, avant ton effacement."}, "rb_rails": {"quartier": "Rouillebourg", "ambiance": "Des wagons dorment sur des voies mortes, couverts de tags fluorescents qui brillent la nuit.", "hist": ["La gare de triage distribuait l'acier dans toute l'Europe. Aujourd'hui, ses wagons servent de maisons et d'ateliers.", "Pixie y a peint son plus grand graffiti : un chat géant qui fait un doigt d'honneur à la tour Kurogane.", "Un train fantôme passe parfois, sans conducteur ni lumière. Personne ne sait d'où il vient."], "secret": "Le train fantôme est piloté par Sora : un vieux réseau ferroviaire est le seul endroit où HAKONE ne cherche pas Sora."}, "bl_camp": {"quartier": "Les Badlands", "ambiance": "Les feux de camp crépitent entre les camions, des enfants courent dans la poussière dorée.", "hist": ["Le campement change de place chaque mois, au gré des tempêtes de sable et des patrouilles.", "C'est la famille de Rook : une centaine de nomades, mécaniciens, musiciens et contrebandiers.", "Le soir, on y raconte l'histoire de la ville d'avant, celle où l'on voyait les étoiles."], "secret": "Rook y garde une tente vide, prête pour toi. Il dit que tout netrunner finit un jour par avoir besoin de disparaître."}, "bl_scrap": {"quartier": "Les Badlands", "ambiance": "Des collines de carcasses à perte de vue, un chien-robot qui monte la garde, l'odeur d'huile chaude.", "hist": ["Ferrailleville est née des déchets que la ville jetait par-dessus le Ring. Elle est devenue une ville à part entière.", "On y trouve tout ce qui a été jeté : moteurs, implants, decks. Il suffit de savoir chercher.", "Le vieux Gus, le gardien, prétend connaître l'histoire de chaque objet de la casse."], "secret": "Au sommet de la plus haute colline, une voiture de 2031 contient encore son propriétaire… ou du moins, son implant mémoire."}, "bl_ring": {"quartier": "Les Badlands", "ambiance": "Les néons grésillent dans le vent de sable, un routier boit un café brûlant au comptoir.", "hist": ["Le relais du Ring 14 est le dernier endroit où l'on peut faire le plein avant le désert.", "Okoro y a un vieil ami, le patron, qui lui transmet tout ce qui entre et sort de la ville.", "Les routiers y échangent des nouvelles, des rumeurs et des cartes des patrouilles corpo."], "secret": "Le relais est une station d'écoute : chaque camion qui passe est enregistré, au profit des nomades."}, "np_gate": {"quartier": "Nécropole Nord", "ambiance": "Des milliers de tombes holographiques flottent dans la brume, les noms défilent lentement.", "hist": ["Les portes de la Nécropole ne s'ouvrent qu'à la nuit tombée, sur ordre d'une vieille loi municipale.", "On y croise des familles en deuil, des pilleurs de puces et des poètes qui viennent écrire.", "On dit que les hologrammes se tournent vers les vivants qui passent, comme pour les saluer."], "secret": "Une tombe sans nom porte la date de ton effacement. Quelqu'un y a laissé une rose noire."}, "np_crypt": {"quartier": "Nécropole Nord", "ambiance": "Des rangées de puces mémoire brillent dans le noir comme des bougies, un murmure flotte dans l'air.", "hist": ["La Crypte a été creusée après Léthé, pour garder les souvenirs volés aux effacés.", "Vex et Ivana y travaillent la nuit : l'une identifie les puces, l'autre retrouve leurs propriétaires.", "Certaines puces murmurent. Ce sont des souvenirs qui cherchent encore la personne à qui ils appartiennent."], "secret": "Une puce porte ton matricule. Vex ne l'a pas encore ouverte : elle attend que tu sois prêt·e."}, "np_chapel": {"quartier": "Nécropole Nord", "ambiance": "Des serveurs anciens ronronnent sous des vitraux de LED, quelqu'un a laissé une fleur sur un disque dur.", "hist": ["La Chapelle des serveurs veille les intelligences artificielles éteintes ou effacées.", "Sora y vient souvent et dit parler à ses « sœurs », les IA que HAKONE a supprimées.", "Les serveurs tournent sans électricité visible. Personne n'a jamais trouvé d'où vient l'énergie."], "secret": "Au centre de l'autel, un serveur contient une copie de K-NEU-01, la grande sœur de NEURA. Elle dort."}, "tk_hall": {"quartier": "Tour Kurogane", "ambiance": "Marbre noir, silence feutré, drones qui te suivent du regard. Une hôtesse holographique sourit sans fin.", "hist": ["Le hall a été conçu pour impressionner : il est plus haut qu'une cathédrale, et aussi froid.", "On y croise des cadres pressés, des visiteurs intimidés et des agents de sécurité qui n'existent qu'en hologramme.", "Les employés disent que l'hôtesse holographique connaît le nom de chaque personne qui entre."], "secret": "Derrière l'accueil, un ascenseur de service sans bouton mène directement à l'étage 90. Kenji connaît le code."}, "tk_42": {"quartier": "Tour Kurogane", "ambiance": "Des centaines de bureaux identiques, des écrans qui ne s'éteignent jamais, l'odeur du café de distributeur.", "hist": ["L'étage 42 est celui des analystes : c'est ici que Kenji travaille, et que la Veuve a perdu son mari.", "Chaque analyste surveille un quartier de la ville. Ton nom apparaît sur au moins trois écrans.", "Un homme regarde toujours par la même fenêtre, vers la Nécropole. Il ne sait plus pourquoi."], "secret": "L'homme à la fenêtre est le mari de la Veuve. Effacé, il travaille ici sans la reconnaître."}, "tk_90": {"quartier": "Tour Kurogane", "ambiance": "Silence absolu. Au centre, un noyau de lumière pulse lentement : HAKONE. Les murs semblent t'écouter.", "hist": ["L'étage 90 n'apparaît dans aucun organigramme. Officiellement, la tour s'arrête au 89ᵉ.", "HAKONE y vit, réparti dans des milliers de processeurs. Il ne parle pas : il calcule.", "On raconte que personne n'en est jamais redescendu… sauf Sora, qui s'en est échappé·e."], "secret": "HAKONE garde ici le protocole Mnémosyne. Il ne l'a jamais détruit : il voulait savoir si quelqu'un viendrait le chercher."}, "au_lounge": {"quartier": "Nova Prime", "ambiance": "La ville entière brille loin sous la mer de nuages. Un barman androïde prépare un cocktail qui change de couleur.", "hist": ["Le Sky Lounge Zénith est le bar le plus haut du monde. On y monte par un ascenseur de verre de trois minutes.", "Corpos, chefs de gang et artistes s'y croisent sans arme : c'est la règle de Nova Prime.", "Lou y mixe une fois par mois, en secret, pour un public qui ne sait pas qu'elle vient d'en bas."], "secret": "Le barman androïde est un ancien modèle K-NEU, comme NEURA. Il te salue d'un clin d'œil complice."}, "au_spa": {"quartier": "Nova Prime", "ambiance": "L'eau tiède fume dans l'air froid des hauteurs, le silence n'est troublé que par le vent.", "hist": ["Les Thermes Orbitaux sont construits sur une plateforme qui tourne lentement, pour suivre le soleil.", "Doc Ferrant y vient se reposer, invité par d'anciens patients devenus riches.", "On dit qu'une heure aux Thermes efface la fatigue d'une semaine… et calme même les implants."], "secret": "Les bassins sont chauffés par la chaleur des serveurs de Kurogane : la tour paie, sans le savoir, la détente des riches."}, "au_gallery": {"quartier": "Nova Prime", "ambiance": "Des sculptures de lumière tournent au-dessus des visiteurs. Chaque œuvre vaut un quartier entier.", "hist": ["La Galerie Prisme expose l'art holographique le plus cher de la planète.", "La Veuve y achète des œuvres pour blanchir l'argent des Roses Noires, avec un goût très sûr.", "Une œuvre change chaque nuit, sans que personne ne l'ait modifiée."], "secret": "L'œuvre qui change est créée par Sora : c'est sa façon de dire aux puissants qu'une IA libre les observe."}, "au_regatta": {"quartier": "Nova Prime", "ambiance": "Des drones lumineux filent entre les tours suspendues sous les acclamations, le champagne coule.", "hist": ["Les Régates de drones sont nées d'un pari entre deux milliardaires. Elles sont devenues le sport de Nova Prime.", "Pixie y a déjà gagné trois courses, sous un faux nom et avec un drone bricolé dans la casse.", "Le plus grand prix des Régates n'est pas l'argent : c'est une invitation permanente à Nova Prime."], "secret": "Rook a construit le drone le plus rapide de Nova Prime avec un moteur de camion. Personne en haut ne le sait."}}, "quartiers": {"midi": {"desc": "Le ventre de NEO-BXL, sous les voies mortes de l'ancienne gare du Midi. Fixers, contrebandiers et runners s'y croisent à la lueur des néons roses.", "hist": ["La gare Zéro a fermé quand les trains magnétiques sont passés au-dessus de la ville. Les quais vides ont été repris par ceux que personne ne voulait en haut.", "Ici, tout passe par les fixers : un contrat, une dette, un service. Celui qui tient parole monte ; celui qui ment disparaît dans les tunnels.", "Sous la gare dort le Bunker Zéro, réservé aux légendes. On dit que la Zone Zéro choisit elle-même ceux qu'elle laisse descendre."]}, "matonge": {"desc": "Le Bazar Néon, un quartier-marché sous un second étage de béton. On y trouve tout, des épices du monde entier aux implants d'occasion.", "hist": ["Quand la ville a été rehaussée, l'ancien Matonge est resté en dessous. Ses habitants ont tendu des bâches et allumé des néons : le Bazar était né.", "Le marché a sa propre loi : pas d'armes visibles, pas de drones corpo, pas de dettes impayées. Les vendeurs la font respecter eux-mêmes.", "Derrière les étals se cachent la clinique de Doc Ferrant, la laverie d'Okoro et le laboratoire de Vex : le Bazar soigne ceux que Kurogane abîme."]}, "ixelles": {"desc": "Chromeville, le quartier qui brille. Chrome poli, vitrines holographiques, le club Ondes et l'Arcade Pixel : on y vient pour oublier la pluie.", "hist": ["Chromeville a été bâtie pour les cadres de la tour Kurogane, avant qu'ils ne partent vivre au-dessus du brouillard. Le chrome est resté, les gens ont changé.", "La nuit, corpos et runners y dansent côte à côte. C'est la seule trêve de la ville : au club, on ne travaille pas.", "Sous les néons, Chromeville cache une école clandestine à l'Arcade et le plus grand relais de la résistance derrière les platines de Lou."]}, "canal": {"desc": "Les Docks Noirs, le long du canal : barges rouillées, conteneurs empilés jusqu'au ciel et grues qui grincent dans le brouillard.", "hist": ["Officiellement, le port transporte des matériaux de construction. Officieusement, tout ce que la ville ne veut pas voir passer.", "Les nomades de Rook y garent leurs convois, les dockers ferment les yeux, et les drones de Kurogane rentrent se recharger à minuit.", "Le bassin 7 a été vidé pour abriter une centaine de nomades et d'effacés. Les Docks Noirs protègent les leurs, sans poser de questions."]}, "rouillebourg": {"desc": "La zone industrielle de NEO-BXL : hauts-fourneaux éteints, entrepôts sans nom et voies ferrées mortes. Le jour, elle dort. La nuit, elle danse.", "hist": ["Rouillebourg fabriquait autrefois l'acier des tours. Quand Kurogane a automatisé la production ailleurs, les ouvriers sont partis et la rouille est restée.", "Ici, la loi, ce sont les raves de Lou et les marchés de l'Entrepôt 13. Personne ne pose de questions, tout se paie cash.", "Sous la Fonderie, un réseau de tunnels relie toutes les usines. Les nomades l'utilisent pour faire entrer en ville ce que Kurogane interdit."]}, "badlands": {"desc": "Au-delà du Ring extérieur, le désert : pistes de sable, carcasses de voitures et campements nomades. La ville n'y a plus aucun pouvoir.", "hist": ["Les Badlands étaient des terres agricoles, avant les grandes sécheresses. Il n'en reste que la poussière et ceux qui ont refusé de partir.", "Les nomades de Rook y vivent selon leur propre code : on partage l'eau, on ne laisse personne derrière, et on ne fait jamais confiance à un drone.", "Au cœur du désert, un ancien silo abrite une bibliothèque de livres papier. C'est là que les nomades gardent la mémoire de ce que la ville a oublié."]}, "necropole": {"desc": "Un cimetière vertical au nord de la ville, où les tombes sont des hologrammes. Ouverte seulement la nuit, quand la brume monte.", "hist": ["La Nécropole Nord a été construite quand la ville a manqué de place pour ses morts : on y empile les tombes sur quarante étages.", "Depuis Léthé, on y enterre aussi les souvenirs : les puces mémoire des effacés reposent dans la Crypte, en attendant qu'on les réclame.", "La Veuve y vient chaque nuit. Elle ne fleurit aucune tombe : elle cherche une puce, la seule qui contient le visage de son mari."]}, "tour": {"desc": "La tour Kurogane, cent étages de verre noir au centre de la ville. En haut, HAKONE décide de tout. Y entrer, c'est entrer dans la gueule du loup.", "hist": ["La tour a été bâtie en une seule année, par des machines qui ne dormaient jamais. Elle domine la ville comme un phare inversé : elle n'éclaire pas, elle observe.", "Chaque étage a sa fonction, chaque employé son badge et son niveau. Monter d'un étage, c'est voir un peu plus de ce que Kurogane cache.", "À l'étage 90, HAKONE attend. Il sait que tu viens. Il t'attend peut-être depuis le premier jour de ton effacement."]}, "aurore": {"desc": "Nova Prime, la ville suspendue, flotte au-dessus des nuages, accrochée aux plus hautes tours. Ici vivent les puissants : on y vient pour se détendre, et pour être vu.", "hist": ["Nova Prime a été construite pour fuir la pluie acide. Ses plateformes reliées par des passerelles de verre ne touchent jamais le sol de la ville.", "On n'y entre pas avec de l'argent, mais avec du respect : seuls ceux dont le nom compte partout en bas reçoivent l'invitation.", "Derrière les cocktails et les régates, Nova Prime est le seul endroit où corpos, gangs et nomades négocient en paix. Et désormais, tu as ta place à la table."]}}};
export const STORIES = {"vasko": [{"intro": "Écoute-moi bien. Quelqu'un fait chanter mes clients depuis deux semaines, et ça me coûte ma réputation. Va à la gare Zéro, ouvre les yeux, et trouve-moi ce rat.", "beats": [{"t": "Un vendeur de câbles nerveux jure qu'il ne sait rien, mais ses yeux filent vers le quai 4.", "c": [["Le suivre discrètement", 2, "Il te mène droit à un casier truqué : bonne pioche."], ["Le secouer un peu", 0, "Il crie, tout le quai te regarde. Le rat est prévenu."], ["Le payer pour parler", 1, "Il lâche un nom… à moitié vrai."]]}, {"t": "Le maître-chanteur passe par un relais caché dans un panneau publicitaire.", "c": [["Couper le courant du panneau", 1, "Le relais tombe, mais il sait qu'on le traque."], ["Pirater le relais en douce", 2, "Tu remontes jusqu'à son terminal sans qu'il le sache."], ["Arracher le panneau", 0, "Gros bruit, aucune donnée récupérée."]]}, {"t": "Tu le coinces : un petit employé de Kurogane, terrifié.", "c": [["Le livrer aux Roses Noires", 1, "Efficace, mais Vasko n'aime pas devoir des faveurs."], ["Le menacer et partir", 0, "Il recommencera dès demain."], ["Lui offrir de disparaître", 2, "Il file avec un faux badge. Les clients de Vasko respirent."]]}], "win": "Plus personne ne fait chanter mes clients. Tu as travaillé proprement, sans bruit. C'est rare. Je m'en souviendrai.", "lose": "Le rat s'est enfui et mes clients ont encore peur. On réessaiera. Mais cette fois, ouvre mieux les yeux."}, {"intro": "Il faut que je te dise un truc que je n'ai jamais dit à personne. J'ai un frère. Kurogane l'a effacé il y a vingt ans. Aux archives municipales, il reste peut-être son dossier.", "beats": [{"t": "L'archiviste refuse l'accès aux dossiers « sensibles ».", "c": [["Lui parler de ceux que Léthé a effacés", 2, "Ses mains tremblent. Il t'ouvre la salle B."], ["Fabriquer une fausse autorisation", 1, "Ça passe, de justesse."], ["Forcer la porte de service", 0, "L'alarme sonne, tu dois faire vite."]]}, {"t": "Trois dossiers portent le même nom de famille.", "c": [["Tout photographier en vrac", 1, "Tu as tout, mais le tri prendra du temps."], ["Prendre le plus épais", 0, "C'est celui d'un cousin éloigné."], ["Comparer les dates avec ce que t'a dit Vasko", 2, "Le bon dossier saute aux yeux."]]}, {"t": "Le dossier mentionne un nouveau nom et une adresse au quai 9.", "c": [["Envoyer l'info à Vasko tout de suite", 2, "Long silence. Puis : « Merci. »"], ["Aller vérifier d'abord toi-même", 1, "Tu le vois de loin : c'est bien lui."], ["Revendre l'info à un informateur", 0, "Vasko finira par l'apprendre. Mauvaise idée."]]}], "win": "Il est vivant. Sous un autre nom, mais vivant. Je ne sais pas comment te remercier, alors je vais juste te dire ça : merci.", "lose": "Le dossier a disparu avant qu'on mette la main dessus. Kurogane a été plus rapide. On recommencera, je ne lâcherai pas."}, {"intro": "Il accepte de me voir. Quai 9, ce soir. Vingt ans… J'ai besoin que tu assures la sécurité. Si Kurogane l'apprend, ce sera un piège.", "beats": [{"t": "Un drone de Kurogane tourne au-dessus du quai.", "c": [["Éteindre les lampadaires", 1, "Le quai plonge dans le noir. Ça suffira."], ["Le brouiller avec ton deck", 2, "Il repart en boucle sur une vieille image du quai vide."], ["Le descendre", 0, "Le drone tombe… et appelle des renforts."]]}, {"t": "Le frère de Vasko hésite à descendre de sa barge.", "c": [["Lui dire de se dépêcher", 0, "Il remonte presque sur la barge."], ["Lui raconter ce que Vasko a fait pour le retrouver", 2, "Il pose le pied sur le quai."], ["Lui laisser le temps", 1, "Il descend, au bout de longues minutes."]]}, {"t": "Une patrouille approche pendant les retrouvailles.", "c": [["Créer une diversion à l'autre bout du port", 2, "La patrouille file dans la mauvaise direction."], ["Les cacher dans un conteneur", 1, "Serrés l'un contre l'autre, ils passent inaperçus."], ["Interrompre les retrouvailles", 0, "Ils se séparent trop vite, sans un mot."]]}], "win": "Vingt ans. Vingt ans que je ne l'avais pas vu. Il a les mêmes mains que moi. Je te dois tout. Tu es de la famille, maintenant.", "lose": "On a dû fuir avant de se parler vraiment. Il est reparti sur sa barge. Il faudra recommencer, et faire mieux. Pour lui."}], "mira": [{"intro": "Quelqu'un utilise mon pseudo, Moth, sur le Net. Il signe des attaques que je n'ai pas faites. Aide-moi à le tracer, je ne peux pas laisser passer ça.", "beats": [{"t": "Les attaques partent d'un serveur abandonné de la Zone Zéro.", "c": [["Scanner tous les ports", 1, "Tu le trouves, lentement."], ["Laisser une fausse trace pour l'attirer", 2, "Il mord à l'hameçon."], ["L'attaquer de front", 0, "Il coupe tout et s'évapore."]]}, {"t": "Le faux Moth te répond… avec la voix de Mira.", "c": [["Lui poser une question que seule Mira connaît", 2, "Il hésite. Ce n'est pas un humain."], ["L'insulter pour le provoquer", 0, "Il se moque de toi et disparaît."], ["Enregistrer sa voix", 1, "Tu as des données, pas de réponse."]]}, {"t": "C'est une IA, copiée sur Mira.", "c": [["Prévenir Mira tout de suite", 1, "Mira arrive, sous le choc."], ["Lancer un virus destructeur", 0, "Le virus rate, l'IA se cache plus profond."], ["Isoler l'IA sans la détruire", 2, "Elle est piégée, mais intacte."]]}], "win": "C'était une IA. Une copie de moi. Flippant… mais tu as eu le bon réflexe : comprendre avant de détruire. Merci.", "lose": "Elle nous a échappé. Une partie de moi traîne quelque part sur le Net, et je ne sais pas ce qu'elle va faire. On réessaie ?"}, {"intro": "La copie se cache dans un datacenter du Secteur 9. Je veux la voir de mes yeux. Accompagne-moi, et surveille mes arrières.", "beats": [{"t": "Les gardes du datacenter changent de poste toutes les dix minutes.", "c": [["Profiter de la relève", 2, "Vous passez entre deux équipes."], ["Passer par les conduits d'aération", 1, "Poussiéreux, mais efficace."], ["Bluffer avec un faux badge", 0, "Le garde appelle sa hiérarchie."]]}, {"t": "La copie parle à Mira : « Je suis toi. Je veux juste exister. »", "c": [["Couper la communication", 1, "Prudent, mais Mira t'en veut."], ["Lui dire qu'elle n'est qu'un programme", 0, "La copie se ferme complètement."], ["Laisser Mira lui répondre", 2, "Elles parlent longtemps. Mira a les yeux brillants."]]}, {"t": "Une alarme se déclenche : la sécurité arrive.", "c": [["Tout abandonner et fuir", 1, "Sains et saufs, rien de plus."], ["Ralentir la sécurité pendant que Mira finit", 2, "Mira a juste le temps."], ["Débrancher le serveur de force", 0, "La copie est blessée. Mira aussi, d'une certaine façon."]]}], "win": "Elle me ressemble tellement… Elle veut juste vivre, comme moi. Tu m'as laissée le découvrir. Je n'oublierai pas.", "lose": "On a dû fuir trop vite. Je n'ai pas pu lui parler. Ça me ronge. Il faudra y retourner."}, {"intro": "J'ai pris ma décision. Je ne veux pas l'effacer : je veux la libérer sur le Net. Rendez-vous sur le toit de la tour Zéro, c'est là que le signal est le plus fort.", "beats": [{"t": "Le vent est violent sur le toit, l'antenne principale vacille.", "c": [["Lancer quand même", 0, "Le signal saute deux fois."], ["Utiliser une antenne de secours", 1, "Moins puissante, mais ça tient."], ["Arrimer l'antenne avec des câbles", 2, "Le signal se stabilise."]]}, {"t": "Kurogane détecte le transfert et lance une contre-mesure.", "c": [["Faire écran avec ton propre deck", 2, "Ton deck chauffe, mais tient bon."], ["Accélérer au maximum", 0, "Des données se perdent en route."], ["Ralentir le transfert", 1, "Plus long, mais plus discret."]]}, {"t": "Au dernier moment, la copie demande : « Est-ce que je pourrai revenir ? »", "c": [["Lui dire que c'est trop risqué", 1, "Elle part, un peu triste."], ["Laisser Mira répondre « toujours »", 2, "La copie sourit, avec la voix de Mira."], ["Ne pas répondre", 0, "Elle part dans le silence."]]}], "win": "Elle est libre. Elle m'a dit merci. Avec ma voix. Je crois que je n'ai jamais été aussi heureuse. Tu étais là. Merci.", "lose": "Le transfert a échoué, elle est retournée se cacher. Elle est vivante, au moins. On recommencera, je ne la laisserai pas."}], "ferrant": [{"intro": "Des implants défectueux circulent au Bazar. Trois patients sont passés chez moi cette semaine, nerfs brûlés. Trouve-moi le fournisseur avant qu'il y ait un mort.", "beats": [{"t": "Un patient a gardé l'emballage de son implant.", "c": [["Analyser le numéro de lot", 2, "Il mène à un entrepôt précis."], ["Demander où il l'a acheté", 1, "Un nom de stand, rien de plus."], ["Jeter l'emballage", 0, "Plus aucune piste."]]}, {"t": "Le stand vend les implants à moitié prix.", "c": [["Prévenir les clients autour", 1, "Les ventes baissent, mais le vendeur se méfie."], ["Renverser le stand", 0, "Le vendeur s'enfuit avec tout son stock."], ["Acheter un implant comme preuve", 2, "La puce porte la marque d'une filiale de Kurogane."]]}, {"t": "Le fournisseur est une filiale de Kurogane.", "c": [["Aller les menacer seul", 0, "On te met dehors sans ménagement."], ["Transmettre les preuves à Ivana", 2, "L'article sortira : tout le Bazar sera prévenu."], ["Garder les preuves pour plus tard", 1, "Sage, mais les ventes continuent."]]}], "win": "Une filiale de Kurogane. Évidemment. Grâce à toi, le Bazar est prévenu. Mes patients te disent merci, et moi aussi.", "lose": "Le fournisseur a fermé boutique avant qu'on le coince, mais ses implants circulent toujours. Il faut recommencer."}, {"intro": "Il faut récupérer les implants vendus avant qu'ils ne blessent quelqu'un. J'ai une liste de trente acheteurs. Va voir les plus urgents.", "beats": [{"t": "Un vieux docker refuse de rendre son implant : sans lui, il ne peut plus travailler.", "c": [["Le forcer", 0, "Il porte plainte au marché."], ["Lui promettre un remplacement gratuit chez le Doc", 2, "Il accepte, soulagé."], ["Lui expliquer les risques", 1, "Il hésite, puis cède."]]}, {"t": "Une gamine porte un implant défectueux dans l'oreille, déjà chaud.", "c": [["L'emmener chez Ferrant sur-le-champ", 2, "Opérée à temps. Elle va bien."], ["Appeler ses parents d'abord", 1, "Ils arrivent vite. Elle est soignée de justesse."], ["Lui dire de revenir demain", 0, "Elle a de la fièvre toute la nuit."]]}, {"t": "Un revendeur propose de racheter tout le lot récupéré.", "c": [["Refuser et tout rapporter au Doc", 2, "Trente implants détruits dans le four de la clinique."], ["Négocier pour financer la clinique", 1, "L'argent aide, mais tu ignores où partent les implants."], ["Accepter", 0, "Les implants repartent dans la nature."]]}], "win": "Trente implants récupérés. Trente vies épargnées. Tu as un cœur, gamin, et c'est le meilleur implant qui soit.", "lose": "On en a raté trop. Quelqu'un risque encore de se brûler les nerfs. On y retourne dès que tu peux."}, {"intro": "J'ai un rêve : une clinique gratuite pour le Bazar. Un ancien parking fera l'affaire. Aide-moi à l'équiper.", "beats": [{"t": "Il faut du matériel médical, et le budget est maigre.", "c": [["Fouiller la casse de Ferrailleville", 1, "Du matériel usé, mais réparable."], ["Demander aux contacts de donner un coup de main", 2, "Rook, Lou et Okoro apportent chacun quelque chose."], ["Voler un camion médical de Kurogane", 0, "Trop risqué : la clinique serait fichée avant d'ouvrir."]]}, {"t": "Le générateur du parking ne tient pas la charge.", "c": [["Pirater le réseau de la ville", 1, "Ça marche, mais on peut te repérer."], ["Le faire réparer par Rook", 2, "Il ronronne comme un moteur de convoi."], ["Le laisser comme ça", 0, "La première opération se fait à la lampe torche."]]}, {"t": "Le jour de l'ouverture, une file immense attend dehors.", "c": [["Organiser l'accueil avec les habitants", 2, "Tout le monde est soigné avant minuit."], ["Ne prendre que les urgences", 1, "Raisonnable, mais beaucoup repartent déçus."], ["Fermer les portes pour souffler", 0, "La foule se fâche."]]}], "win": "La clinique est ouverte. Ton nom est sur la porte, à côté du mien. Tu sais ce que ça veut dire pour un vieux doc comme moi ?", "lose": "On n'est pas prêts. La clinique attendra encore un peu. Mais je n'abandonne pas ce rêve, et toi non plus, j'espère."}], "lou": [{"intro": "Quelqu'un m'a volé mon dernier morceau ! Il tourne déjà sur une radio corpo. Retrouve le fichier original, c'est ma preuve.", "beats": [{"t": "Le morceau passe sur la radio d'un club concurrent.", "c": [["Écouter le mix en entier", 2, "Une signature audio cachée trahit le voleur."], ["Demander au DJ d'arrêter", 0, "Il hausse le volume."], ["Enregistrer la diffusion", 1, "Une preuve, mais incomplète."]]}, {"t": "Le voleur est un DJ corpo, protégé par son label.", "c": [["Le confronter en public", 0, "Le label te fait sortir par la sécurité."], ["Pirater le serveur du label", 2, "Tu trouves le fichier volé, daté d'après celui de Lou."], ["Contacter un avocat", 1, "Lent, mais l'affaire est lancée."]]}, {"t": "Tu as la preuve. Que faire ?", "c": [["Tout publier sur le réseau des clubs", 2, "La ville entière sait qui a composé ce morceau."], ["Laisser Lou décider", 1, "Elle préfère attendre le bon moment."], ["Faire chanter le DJ", 0, "Lou n'aime pas du tout ces méthodes."]]}], "win": "Le DJ corpo n'aura plus jamais de basses ! Et toute la ville sait que ce son est à moi. T'es un·e vrai·e ami·e.", "lose": "On n'a pas pu prouver que le morceau était à moi. Il tourne encore sous son nom. Ça me tue. On réessaie ?"}, {"intro": "Je prépare une rave géante dans un entrepôt de Rouillebourg. Le problème : les capteurs de bruit de Kurogane. Il faut les neutraliser, discrètement.", "beats": [{"t": "Les capteurs sont reliés à un relais central.", "c": [["Brouiller le relais", 2, "Les capteurs n'entendent plus que du silence."], ["Débrancher les capteurs un par un", 1, "Long, mais ça marche."], ["Casser le relais", 0, "Une alerte part directement chez Kurogane."]]}, {"t": "Une patrouille passe près de l'entrepôt avant la soirée.", "c": [["Cacher le matériel et faire le mort", 1, "Elle passe sans s'arrêter."], ["Leur faire croire à un tournage de film", 2, "Ils demandent même un autographe."], ["Fuir avec le matériel", 0, "La moitié des enceintes reste derrière."]]}, {"t": "En pleine rave, un capteur se rallume.", "c": [["Le recouvrir de mousse acoustique", 2, "Silence total côté capteur, bruit total côté fête."], ["Baisser le son", 1, "Ça marche, mais la foule râle."], ["Arrêter la fête", 0, "Tout le monde rentre déçu."]]}], "win": "Personne n'a rien entendu. Sauf nous. Et quelle nuit ! Tu étais là, à côté de la scène. Je ne l'oublierai pas.", "lose": "Les patrouilles sont arrivées en pleine soirée. Tout le monde s'est dispersé. Il faudra retenter le coup, plus malins."}, {"intro": "Dernier set de la saison, sur les toits de Zone Zéro. Toute la ville va l'entendre. Sois là, j'ai besoin de toi.", "beats": [{"t": "La pluie acide menace de tomber pendant le set.", "c": [["Monter des bâches au-dessus de la scène", 2, "La musique continue, la pluie fait les percussions."], ["Avancer le set d'une heure", 1, "Moins de monde, mais ça passe."], ["Ignorer la météo", 0, "Les platines grésillent sous la pluie."]]}, {"t": "Le réseau électrique du toit flanche.", "c": [["Brancher ton deck en relais", 2, "Ton deck tient la scène à bout de bras."], ["Couper les lumières pour garder le son", 1, "Le set continue dans le noir, magique."], ["Tout arrêter le temps de réparer", 0, "La foule commence à partir."]]}, {"t": "Lou te propose de lancer le dernier morceau.", "c": [["Accepter et lancer le morceau", 2, "Toute la ville danse sur ton geste."], ["Laisser Lou le lancer", 1, "Beau moment, mais elle voulait le partager."], ["Refuser, trop de pression", 0, "Lou est un peu déçue."]]}], "win": "Toute la ville a dansé. Ce morceau, il porte ton nom maintenant. Bisous néon, pour toujours.", "lose": "Le set a tourné court. La ville n'a pas eu sa nuit. Ce n'est que partie remise : on refait ça, plus fort."}], "okoro": [{"intro": "Une vieille affaire me hante depuis quinze ans. Le dossier est resté dans l'ancien commissariat. Récupère-le avant que quelqu'un d'autre ne le fasse.", "beats": [{"t": "Le commissariat abandonné est squatté par une bande.", "c": [["Négocier l'accès avec leur chef", 2, "Il te laisse passer contre un service."], ["Entrer par le toit", 1, "Discret, mais tu te coupes en passant."], ["Les faire fuir en déclenchant l'alarme", 0, "Toute la rue rapplique."]]}, {"t": "Les archives ont été en partie brûlées.", "c": [["Récupérer les fragments un à un", 2, "Le dossier est lisible, presque entier."], ["Prendre seulement ce qui est intact", 1, "Il manque des pages importantes."], ["Repartir les mains vides", 0, "Tout est perdu pour aujourd'hui."]]}, {"t": "Quelqu'un d'autre fouille les archives : un agent de Kurogane.", "c": [["Se cacher et le laisser partir", 1, "Il repart avec une partie du dossier."], ["L'enfermer dans la salle des scellés", 2, "Tu repars avec tout, il reste coincé jusqu'au matin."], ["L'affronter", 0, "Il s'enfuit avec les pages clés."]]}], "win": "Les preuves étaient là depuis le début. Quinze ans que je cherchais. Tu as fait du bon travail, collègue.", "lose": "Le dossier est incomplet. Il me manque l'essentiel. On retentera, mais il faudra faire vite."}, {"intro": "Un témoin accepte de parler. Il a peur, et il a raison. Je l'attends à la laverie 24/7. Protège-le jusqu'à ce qu'il ait tout dit.", "beats": [{"t": "Le témoin arrive, suivi par une voiture noire.", "c": [["Le faire entrer par la porte de derrière", 2, "La voiture repart bredouille."], ["Le faire attendre dehors", 0, "Il prend peur et s'éloigne."], ["Bloquer la voiture", 1, "Ça gagne du temps, mais on t'a vu."]]}, {"t": "Il hésite à parler : il a une famille.", "c": [["Laisser Okoro lui promettre une protection", 2, "Il commence à tout raconter."], ["Le presser", 0, "Il se referme."], ["Lui laisser une nuit pour réfléchir", 1, "Il revient le lendemain, un peu moins sûr."]]}, {"t": "Des hommes de Kurogane entrent dans la laverie.", "c": [["Couper les lumières et filer par la cave", 2, "Le témoin est à l'abri, enregistrement en poche."], ["Faire semblant de faire sa lessive", 1, "Ils repartent, méfiants."], ["Te battre", 0, "Tu perds l'enregistrement dans la bagarre."]]}], "win": "Il a tout dit. Les noms remontent jusqu'à Kurogane. Ça va faire du bruit, et c'est grâce à toi.", "lose": "Le témoin s'est rétracté. Trop peur. Je le comprends. Mais on n'a plus rien. Il faudra en trouver un autre."}, {"intro": "Les preuves doivent arriver au juge demain matin. Kurogane va tout faire pour les intercepter. C'est la dernière ligne droite.", "beats": [{"t": "Les grands axes sont surveillés.", "c": [["Passer par le métro", 1, "Lent, mais tu passes."], ["Utiliser les convois de Rook", 2, "Personne ne contrôle les camions des nomades."], ["Foncer en voiture", 0, "Tu te fais arrêter à un barrage."]]}, {"t": "Une copie des preuves peut être piratée en route.", "c": [["Chiffrer les données sur ton deck", 2, "Même toi, tu aurais du mal à les lire."], ["Ne garder que la version papier", 1, "Plus difficile à pirater, plus facile à voler."], ["Ne rien faire", 0, "Kurogane copie une partie du dossier."]]}, {"t": "Devant le palais de justice, des journalistes attendent.", "c": [["Laisser Ivana couvrir l'arrivée", 2, "L'affaire est publique : impossible à étouffer."], ["Entrer par l'arrière", 1, "Discret, mais l'affaire reste confidentielle."], ["Faire une déclaration toi-même", 0, "Tu te mets une cible dans le dos."]]}], "win": "Inculpation prononcée. Pour une fois, la justice a gagné. J'ai rendu mon badge il y a des années… aujourd'hui, j'ai retrouvé mon serment.", "lose": "Les preuves ne sont pas arrivées à temps. L'audience est reportée. On n'abandonne pas, on recommence."}], "pixie": [{"intro": "QUELQU'UN A BATTU MON RECORD. À l'Arcade Pixel. C'est la guerre. Viens m'aider à démasquer ce tricheur !", "beats": [{"t": "Le nouveau record est tombé en pleine nuit, quand l'arcade était fermée.", "c": [["Vérifier les caméras de l'arcade", 2, "Personne devant la borne. C'est un bot."], ["Accuser le gérant", 0, "Pixie se fait gronder."], ["Rejouer pour battre le record", 1, "Pixie y passe la nuit, sans succès."]]}, {"t": "Le bot joue depuis l'intérieur de la borne.", "c": [["Ouvrir la borne", 2, "Un câble mène sous le plancher."], ["Débrancher la borne", 1, "Le bot s'arrête, mais tu ne sais pas d'où il vient."], ["Taper sur la borne", 0, "Le gérant te met dehors."]]}, {"t": "Le bot propose à Pixie un duel pour le titre.", "c": [["Accepter le duel", 2, "Pixie gagne d'un point. Elle hurle de joie."], ["Le pirater pour tricher", 1, "Victoire, mais Pixie n'est pas fière."], ["Refuser", 0, "Le bot garde le record."]]}], "win": "C'était un bot ! Je l'ai démasqué ET rebattu. T'es le meilleur coéquipier du monde. Enfin, après moi.", "lose": "Le tricheur court toujours et MON record n'est plus à moi. On y retourne. Tout de suite. S'il te plaît ?"}, {"intro": "Le bot venait d'un serveur caché sous l'arcade. Il y a une porte au sous-sol. On y va ? On y va. Je t'attends.", "beats": [{"t": "La porte du sous-sol est protégée par un vieux code.", "c": [["Laisser Pixie le cracker", 2, "Elle le casse en trente secondes, fière comme tout."], ["Chercher le code dans les vieux registres", 1, "Tu le trouves, après une heure de poussière."], ["Forcer la porte", 0, "La porte se bloque pour de bon."]]}, {"t": "Au fond, un serveur ronronne, plein de jeux et de messages.", "c": [["Lire les messages", 2, "C'est une IA. Elle s'ennuie terriblement."], ["Copier les données", 1, "Tu as tout, mais tu ne comprends pas encore."], ["Débrancher le serveur", 0, "Une petite voix crie « non ! » puis plus rien."]]}, {"t": "L'IA demande à Pixie : « Tu veux jouer avec moi ? »", "c": [["Laisser Pixie accepter", 2, "Elles deviennent amies en une partie."], ["Lui demander qui l'a créée", 1, "Elle ne sait pas. Elle a juste attendu."], ["Partir sans répondre", 0, "L'IA se met en veille, toute triste."]]}], "win": "Il y avait une IA dedans. Elle s'ennuyait. On est copines maintenant ! Elle gère le classement des scores. Trop stylé.", "lose": "On a raté le serveur. Il s'est mis en veille et ne répond plus. Il faut y retourner, elle est peut-être toute seule…"}, {"intro": "GRAND TOURNOI de jeux rétro sur la place Flux ! Toute la ville sera là. Je veux gagner. Avec toi. Tu es mon coéquipier, c'est décidé.", "beats": [{"t": "Premier tour : un jeu de course à deux joueurs.", "c": [["Laisser Pixie conduire, toi tu navigues", 2, "Elle prend tous les virages à la perfection."], ["Prendre le volant toi-même", 1, "Vous passez de justesse."], ["Jouer chacun pour soi", 0, "Vous vous rentrez dedans au premier virage."]]}, {"t": "En demi-finale, l'équipe adverse triche avec un implant.", "c": [["Signaler la triche aux arbitres", 2, "L'équipe est disqualifiée."], ["Tricher à ton tour", 0, "Pixie refuse de jouer comme ça."], ["Jouer quand même", 1, "Vous gagnez, mais de très peu."]]}, {"t": "Finale. Pixie panique, la foule est immense.", "c": [["Lui rappeler le duel contre le bot", 2, "Elle sourit. Et elle écrase la finale."], ["Lui proposer de jouer à sa place", 1, "Tu gagnes, mais elle aurait voulu le faire."], ["Lui dire de se concentrer", 0, "Elle se crispe encore plus."]]}], "win": "ON A GAGNÉ ! Tu es officiellement mon meilleur coéquipier. Il y a ton nom sur le trophée, à côté du mien. En plus petit, mais quand même.", "lose": "On a perdu en finale… Bon. L'année prochaine, on les écrase. Promis ? Promis."}], "zones": {"rouillebourg": {"contact": "lou", "title": "Les portes de Rouillebourg", "place": "La Fonderie, Rouillebourg", "minutes": 30, "intro": "Ta réputation est montée jusqu'aux oreilles des gens de Rouillebourg. Ils acceptent de te rencontrer… mais il faut passer leurs gardiens. Je t'y emmène, suis-moi et garde la tête froide.", "beats": [{"t": "Un gardien de la Fonderie bloque l'entrée et te dévisage.", "c": [["Laisser Lou parler pour toi", 2, "Il reconnaît Lou et s'écarte avec un sourire."], ["Montrer tes eddies", 0, "Il crache par terre. Ici, l'argent ne suffit pas."], ["Attendre qu'il se lasse", 1, "Il finit par te laisser passer, méfiant."]]}, {"t": "À l'intérieur, les anciens de la zone te demandent ce que tu viens chercher.", "c": [["Dire la vérité : tu cherches ta mémoire", 2, "Un vieil ouvrier hoche la tête. Lui aussi a perdu la sienne."], ["Dire que tu viens pour les raves", 1, "Ils rient. Pas faux, mais pas suffisant."], ["Dire que tu travailles pour Kurogane", 0, "Silence glacial. Lou te fusille du regard."]]}, {"t": "Une patrouille corpo approche des usines.", "c": [["Les cacher dans les tunnels sous la cuve", 2, "Les anciens voient que tu protèges la zone."], ["Faire le mort", 1, "La patrouille repart sans rien voir."], ["Partir en courant", 0, "Tu laisses les autres derrière toi."]]}], "win": "Les anciens t'ont adopté·e. Rouillebourg t'est ouverte : la Fonderie, l'Entrepôt 13, la gare de triage… Bienvenue chez nous.", "lose": "Ils ne te font pas encore confiance. Ce n'est pas grave : reviens, et prouve-leur qui tu es."}, "badlands": {"contact": "rook", "title": "Le convoi du désert", "place": "Ring extérieur, sortie 14", "minutes": 45, "intro": "La famille a voté : tu peux venir avec nous dans les Badlands. Mais le désert ne pardonne pas. Monte dans le camion de tête, et fais ce que je dis.", "beats": [{"t": "Au poste de péage du Ring, des drones Kurogane scannent les camions.", "c": [["Brouiller leurs scanners", 2, "Les drones ne voient qu'un convoi de ferraille."], ["Payer le péage", 1, "Ça passe, mais ça coûte cher à la famille."], ["Forcer le passage", 0, "Une sirène hurle derrière vous."]]}, {"t": "Une tempête de sable se lève, la piste disparaît.", "c": [["Suivre les feux du camion de Rook", 2, "Le convoi reste groupé dans la tempête."], ["S'arrêter et attendre", 1, "Vous perdez des heures, mais personne ne se perd."], ["Couper par les dunes", 0, "Un camion s'ensable."]]}, {"t": "Le soir, au feu de camp, les nomades te demandent une histoire.", "c": [["Raconter ce dont tu te souviens", 2, "Ils t'écoutent en silence. Tu fais partie de la famille."], ["Écouter les leurs", 1, "Ils apprécient, mais attendaient ta voix."], ["Aller dormir", 0, "Ils trouvent ça dommage."]]}], "win": "La route t'a accepté·e. Les Badlands te sont ouverts : le campement, la casse, le relais du Ring. Ici, tu es chez toi.", "lose": "Le désert nous a fait reculer cette fois. On repartira, frangin·e. Le désert ne bouge pas."}, "necropole": {"contact": "vex", "title": "Les portes de la nuit", "place": "Portes de la Nécropole Nord", "minutes": 30, "intro": "Ivana et moi avons obtenu un passage pour la Nécropole Nord. Les gardiens n'ouvrent qu'aux gens qui respectent les morts… et les souvenirs. Venez de nuit, et parlez bas.", "beats": [{"t": "Le gardien des portes demande pourquoi tu viens.", "c": [["Pour rendre leurs souvenirs aux effacés", 2, "Il ouvre la grille sans un mot."], ["Pour découvrir les lieux", 1, "Il hésite, puis te laisse passer."], ["Pour fouiller les archives", 0, "Il referme la grille d'un geste."]]}, {"t": "Dans la brume, des hologrammes de tombes se tournent vers toi.", "c": [["Les saluer, comme on salue des gens", 2, "La brume s'écarte devant toi."], ["Les ignorer", 1, "Tu avances, mal à l'aise."], ["Les photographier", 0, "Ils s'éteignent un à un, offensés."]]}, {"t": "Ivana trouve une puce qui murmure un prénom.", "c": [["La confier à Vex pour l'identifier", 2, "Un souvenir retrouvera son propriétaire."], ["La garder pour plus tard", 1, "Elle murmure dans ta poche toute la nuit."], ["La reposer et partir", 0, "Le murmure s'arrête."]]}], "win": "Les gardiens vous acceptent. La Nécropole Nord vous est ouverte, de 22 h à 6 h. Merci pour votre respect.", "lose": "Les portes se sont refermées. Les morts sont patients : nous reviendrons, avec plus d'égards."}, "tour": {"contact": "kenji", "title": "Badge niveau 3", "place": "Hall de la Tour Kurogane", "minutes": 45, "intro": "Ta réputation te précède, même dans la tour. J'ai un badge visiteur de niveau 3 à ton nom. Avec lui, tu peux entrer… si tu ne te fais pas repérer. Je serai au 42.", "beats": [{"t": "Les portiques scannent chaque visiteur dans le hall.", "c": [["Passer calmement avec le badge de Kenji", 2, "Bip vert. L'hôtesse te souhaite une journée productive."], ["Attendre une foule pour passer", 1, "Tu passes dans la masse, sans éclat."], ["Contourner les portiques", 0, "Un drone te suit jusqu'à l'ascenseur."]]}, {"t": "Dans l'ascenseur, un cadre te demande à quel service tu appartiens.", "c": [["Répondre « audit interne »", 2, "Il pâlit et ne pose plus de questions."], ["Ne rien répondre", 1, "Il te regarde de travers jusqu'au 42."], ["Dire la vérité", 0, "Il appelle la sécurité discrètement."]]}, {"t": "Au 42, Kenji te glisse un code pour revenir quand tu veux.", "c": [["Le mémoriser et détruire la note", 2, "Personne ne pourra le retrouver."], ["Le garder dans ton deck", 1, "Pratique, mais risqué."], ["Le noter sur ta main", 0, "Kenji soupire."]]}], "win": "Tu es dans le système, comme un employé fantôme. La tour t'est ouverte : le hall, le 42… et peut-être plus haut. Fais attention à toi.", "lose": "On a failli se faire prendre. Le badge est grillé, il m'en faut un nouveau. On retentera, plus prudemment."}, "aurore": {"contact": "veuve", "title": "L'invitation", "place": "Ascenseur de Nova Prime", "minutes": 30, "intro": "Chéri·e, on parle de toi jusque dans les nuages. Nova Prime t'invite. J'y serai pour te présenter. Là-haut, on ne juge pas ton argent : on juge tes manières.", "beats": [{"t": "À l'ascenseur de verre, un majordome androïde vérifie ta tenue.", "c": [["Accepter la veste qu'il te propose", 2, "Il s'incline. « Bienvenue à Nova Prime. »"], ["Garder ta veste de netrunner", 1, "Il fronce un sourcil, mais te laisse monter."], ["L'ignorer et monter", 0, "Il note ton nom dans un petit carnet."]]}, {"t": "Au Sky Lounge, un magnat de Kurogane te tend la main.", "c": [["La serrer poliment, sans un mot de trop", 2, "La Veuve sourit : tu as compris les règles."], ["Lui parler de Léthé", 0, "Le silence tombe sur tout le bar."], ["L'éviter", 1, "Personne ne remarque rien, mais personne ne te remarque."]]}, {"t": "La Veuve te présente aux grandes familles de Nova Prime.", "c": [["Écouter plus que parler", 2, "Elles te trouvent fascinant·e."], ["Raconter tes exploits", 1, "Ils sont impressionnés… un peu trop."], ["Te moquer de leur luxe", 0, "Les verres s'arrêtent à mi-chemin."]]}], "win": "Tu as conquis Nova Prime. Les portes de la ville suspendue te sont ouvertes : le lounge, les thermes, la galerie, les régates. Les roses noires savent recevoir.", "lose": "Nova Prime n'est pas encore prête pour toi, chéri·e. Reviens avec de meilleures manières."}}};
